const raw = ($json.output || '').trim();
let result = {
  out_of_scope: false,
  needs_human: true,
  categorie_produit: 'indetermine',
  nom_produit_detecte: null,
  elements_fournis: [],
  elements_manquants: [],
  template_complete: false,
  motif_contact: 'GAR-Modalité-condition de garantie',
  email_subject: '',
  email_body: '',
  language: 'fr'
};

try {
  const match = raw.match(/\{[\s\S]*\}/);
  if (match) {
    const parsed = JSON.parse(match[0]);
    result = {
      out_of_scope: parsed.out_of_scope || false,
      needs_human: parsed.out_of_scope ? true : (parsed.needs_human || false),
      categorie_produit: parsed.categorie_produit || result.categorie_produit,
      nom_produit_detecte: parsed.nom_produit_detecte || null,
      elements_fournis: parsed.elements_fournis || [],
      elements_manquants: parsed.elements_manquants || [],
      template_complete: parsed.template_complete || false,
      motif_contact: parsed.motif_contact || result.motif_contact,
      email_subject: parsed.email_subject || '',
      email_body: parsed.email_body || '',
      language: parsed.language || 'fr'
    };
  }
} catch(e) {
  console.error('Parsing JSON échoué:', e.message);
}

// Filet de sécurité : si le modèle a oublié de résoudre le placeholder, on le fait ici
if (result.email_body.includes('[NOM_PRODUIT]')) {
  if (result.nom_produit_detecte) {
    result.email_body = result.email_body.split('[NOM_PRODUIT]').join(result.nom_produit_detecte);
  } else {
    result.email_body = result.email_body.split(' [NOM_PRODUIT]').join('').split('[NOM_PRODUIT]').join('');
  }
}

const pj = $('Extraire pièces jointes').item.json;

return {
  json: {
    ...result,
    contact_email: pj.contact_email,
    case_id: pj.case_id,
    pieces_jointes_count: pj.pieces_jointes_count || 0
  }
};

const item = $json;

const lignes = [
  'Analyse Agent Garantie (IA) — dossier de nouvelle demande',
  `Catégorie produit : ${item.categorie_produit || 'indetermine'}`,
  `Nom produit détecté : ${item.nom_produit_detecte || 'non détecté'}`,
  `Pièces jointes déjà sur le dossier : ${item.pieces_jointes_count ?? 0}`,
  `Dossier complet : ${item.template_complete ? 'oui' : 'non'}`,
  `Éléments fournis : ${(item.elements_fournis || []).join(', ') || 'aucun'}`,
  `Éléments manquants : ${(item.elements_manquants || []).join(', ') || 'aucun'}`,
  `Motif contact : ${item.motif_contact || ''}`,
  `Escalade humaine : ${item.needs_human ? 'oui' : 'non'}`,
  `Hors périmètre : ${item.out_of_scope ? 'oui' : 'non'}`
];

return {
  json: {
    ...item,
    internal_comment: lignes.join('\n')
  }
};
